    private function verifyLinks(int $bookingId,array $plan,iterable $items): void { $approved=[];foreach($plan['items']??[] as $p)$approved[(int)($p['id']??0)]=$p;foreach($items as $item){if(!$item->source_table||!$item->source_id||!$item->booking_service_id||!$item->product_service_id)throw new \RuntimeException('Incomplete supplementary materialization link.');$master=$this->masterFor((string)$item->product_type);if((int)$master['id']!==(int)$item->product_service_id)throw new \RuntimeException('Product Service link changed.');$p=$approved[(int)$item->id]??[];$source=(array)DB::table($item->source_table)->where('id',$item->source_id)->first();if(!$source)throw new \RuntimeException('Materialized source row is missing.');$product=strtolower((string)$item->product_type);if($product==='hotel'){$resolved=$this->hotelStore->resolve();$mode=strtolower((string)($resolved['ownership_mode']??''));if(!$resolved||$resolved['table']!==$item->source_table)throw new \RuntimeException('Hotel resolver ownership mismatch.');if($mode==='direct_booking'){if(!$resolved['booking_column']||((int)($source[$resolved['booking_column']]??0)!==$bookingId))throw new \RuntimeException('Hotel direct ownership mismatch.');if(($resolved['service_link_column']??null)&&((int)($source[$resolved['service_link_column']]??0)!==(int)$item->booking_service_id))throw new \RuntimeException('Hotel service ownership mismatch.');}elseif($mode==='service_link'){if(!$resolved['service_link_column']||((int)($source[$resolved['service_link_column']]??0)!==(int)$item->booking_service_id))throw new \RuntimeException('Hotel service-link ownership mismatch.');}else throw new \RuntimeException('Unknown Hotel ownership mode.');}else{if(isset($source['booking_id'])&&(int)$source['booking_id']!==$bookingId)throw new \RuntimeException('Materialized source booking ownership is invalid.');if(isset($source['booking_service_id'])&&(int)$source['booking_service_id']!==(int)$item->booking_service_id)throw new \RuntimeException('Materialized source service ownership is invalid.');}$allowed=(string)($p['native_table']??($product==='air'?'air_ticket_details':($product==='visa'?'booking_visa_services':$item->source_table)));if($allowed!==(string)$item->source_table)throw new \RuntimeException('Materialized source table is not planner-approved.');if(!DB::table('booking_services')->where('id',$item->booking_service_id)->where('booking_id',$bookingId)->where('product_service_id',$item->product_service_id)->exists())throw new \RuntimeException('Materialized service link is invalid.');if(in_array($product,['air','visa'],true)&&isset($source['booking_passenger_id'])){$s=json_decode((string)$item->product_snapshot,true)?:[];$pid=(int)($s['booking_passenger_id']??$item->booking_passenger_id??0);if($pid>0&&(int)$source['booking_passenger_id']!==$pid)throw new \RuntimeException('Materialized source passenger ownership is invalid.');}}}
    private function resetTravelReady(int $bookingId): void { $cols=Schema::getColumnListing('bookings');$update=[];foreach(['travel_status','readiness_status','travel_readiness_status'] as $column)if(in_array($column,$cols,true)){ $value=$this->readinessValue($column);if($value===null)throw new \RuntimeException('No proven pending travel value for '.$column);$update[$column]=$value;}if($update)DB::table('bookings')->where('id',$bookingId)->update($update); }
    private function readinessValue(string $column): ?string { return $this->enumCompatible('bookings',$column,['pending','PendingTravel','pending_travel','Pending']); }
    private function enumCompatible(string $table,string $column,array $preferred): ?string { foreach((array)Schema::getColumns($table) as $meta){$name=(string)($meta['name']??$meta->name??'');if($name!==$column)continue;$type=strtolower((string)($meta['type_name']??$meta['type']??$meta->type_name??$meta->type??''));if(str_contains($type,'enum')){preg_match_all("/'([^']+)'/",$type,$m);foreach($preferred as $want)foreach($m[1]??[] as $actual)if(strtolower($actual)===strtolower($want))return$actual;return null;}if($column==='travel_status')return'pending';return null;}return null; }
