    private function putFirst(array &$row,array $columns,array $aliases,mixed $value): void { if($value===null||$value==='')return;foreach($aliases as $alias)if(in_array($alias,$columns,true)){$row[$alias]=$value;return;} }
    private function putAll(array &$row,array $columns,array $aliases,mixed $value): void { foreach($aliases as $alias)if(in_array($alias,$columns,true))$row[$alias]=$value; }
    private function first(array $row,array $keys): mixed { foreach($keys as $key)if(isset($row[$key])&&$row[$key]!=='')return$row[$key];return null; }
    private function airGroupKeyForItem(int $id,array $groups): ?string { $matches=[];foreach($groups as $g)if(($g['product_type']??'')==='air'&&in_array($id,array_map('intval',$g['item_ids']??[]),true))$matches[]=(string)($g['group_key']??'');if(count($matches)!==1||$matches[0]==='')throw new \RuntimeException('Air item must resolve to exactly one planner group.');return$matches[0]; }
